const body = $input.first().json.body || {};
const leads = Array.isArray(body.leads) ? body.leads : [];
return leads.map(l => ({ json: {
  id: l.id || '',
  name: l.name || '',
  city: l.city || '',
  state: l.state || '',
  country: l.country || 'India',
  website: l.website || ''
}}));

// Pair each company result back with its lead (same order as Split Leads)
const leads = $('Split Leads').all().map(i => i.json);
const results = $input.all().map(i => i.json);
return leads.map((l, idx) => {
  const res = results[idx] || {};
  const org = ((res.organizations || res.accounts || [])[0]) || {};
  return { json: {
    ...l,
    org_phone: org.phone || (org.primary_phone && org.primary_phone.number) || '',
    org_website: org.website_url || l.website || '',
    org_domain: org.primary_domain || ''
  }};
});

