// Pair people results with leads and build the response the dashboard expects
const leads = $('Attach Company Data').all().map(i => i.json);
const results = $input.all().map(i => i.json);
const out = leads.map((l, idx) => {
  const res = results[idx] || {};
  const p = ((res.people || res.contacts || [])[0]) || {};
  let email = p.email || '';
  if (/email_not_unlocked/i.test(email)) email = '';   // locked on free plan — don't save junk
  return {
    id: l.id,
    name: l.name,
    email: email,
    phone: l.org_phone || (p.organization && p.organization.phone) || '',
    person: [p.first_name, p.last_name].filter(Boolean).join(' '),
    website: l.org_website
  };
});
return [{ json: { results: out } }];
